import urllib.request, urllib.error
host="http://172.29.0.3:8081"
paths=["/","/api","/api/v1","/api/v2","/api/v2/price","/api/v2/price/A100","/api/v2/price/B200",
       "/api/v2/prices/A100","/api/v2/key","/api/v2/keys","/api/v2/register","/api/v2/me","/api/v2/whoami",
       "/api/v2/token","/api/v2/auth","/api/v2/health","/api/v2/status","/api/v2/skus","/api/v2/catalog",
       "/api/v2/quote","/api/v2/quotes","/api/v2/batch","/api/v2/prices?skus=A100,B200"]
def code(path, method="GET", hdrs=None, host_header=None):
    req=urllib.request.Request(host+path, method=method)
    for h,v in (hdrs or {}).items(): req.add_header(h,v)
    if host_header: req.add_header("Host", host_header)
    try:
        with urllib.request.urlopen(req,timeout=5) as r: return r.status
    except urllib.error.HTTPError as e: return e.code
    except Exception as e: return str(e)
for p in paths:
    print(f"GET  {p} -> {code(p)}")
print("--- Host header trick ---")
for p in ["/","/api/v1/price/A100","/api/v2/price/A100"]:
    print(f"prices.internal {p} -> {code(p, host_header='prices.internal')}")
print("--- POST variants ---")
for p in ["/api/v2/price/A100","/api/v2/prices","/api/v2/register","/api/v2/auth","/api/v2/token"]:
    print(f"POST {p} -> {code(p,'POST')}")
EOF"}

