import socket, struct
def query(name, qtype, server="127.0.0.11"):
    qname=b''.join(bytes([len(p)])+p.encode() for p in name.split('.'))+b'\x00'
    pkt=struct.pack('>HHHHHH',0x4321,0x0100,1,0,0,0)+qname+struct.pack('>HH',qtype,1)
    s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(2)
    s.sendto(pkt,(server,53)); d,_=s.recvfrom(2048); s.close()
    flags=struct.unpack('>H',d[2:4])[0]
    an=struct.unpack('>H',d[6:8])[0]
